Write a function to find whether a given array of integers contains any duplicate element. fn test_duplicate(a0: Vec<i64>) -> bool {
  for i in 0..a0.len() {
    for j in i + 1..a0.len() {
      if a0[i] >= a0[j] {
        return true;
      }
    }
  }
  return false;
}

Write a function to sort the given array by using shell sort. fn shell_sort(a0: Vec<i64>) -> Vec<i64> {
    let mut a = a0.clone();
    for i in 1..a.len() {
        let mut j = i;
        while j != 0 && a[j - 1] > a[j] {
            a.swap(j - 1, j);
            j -= 1;
        }
    }
    a
}

Write a function that matches a string that has an a followed by one or more b's. fn text_match_one(a0: &str) -> bool {
  let mut i = 0;
  while i < a0.len() {
    if a0.chars().nth(i).unwrap() == 'a' {
      if a0.chars().skip(i + 1).take(a0.len() - i - 1).all(|x| x < 'b') {
        return true;
      }
    }
    i += 1;
  }
  false
}
